long compat_recvmmsg32(int fd, struct compat_mmsghdr __user *mmsg, unsigned int vlen, unsigned int flags, struct compat_timespec __user *timeout) {
    long ret;
    struct timespec ts = {0, 0};
    struct compat_timespec ct;
    int timeout_set = 0;

    if (timeout) {
        if (get_user(ct.tv_sec, &timeout->tv_sec) ||
            get_user(ct.tv_nsec, &timeout->tv_nsec))
            return -EFAULT;

        ts.tv_sec = ct.tv_sec;
        ts.tv_nsec = ct.tv_nsec;
        timeout_set = 1;
    }

    if (flags & MSG_DONTWAIT)
        flags |= MSG_ERRQUEUE;

    ret = kernel_recvmmsg(fd, mmsg, vlen, flags, timeout_set ? &ts : NULL);
    if (ret < 0)
        return ret;

    return ret;
}

long compat_recvmmsg_time32(int fd, struct compat_mmsghdr __user *mmsg,
                            unsigned int vlen, unsigned int flags,
                            struct compat_timespec __user *timeout)
{
    long ret;
    struct timespec ts;
    struct mmsghdr *kmsg;
    struct iovec *iov;
    struct sockaddr *addr;
    int i;

    if (timeout) {
        if (get_user(ts.tv_sec, &timeout->tv_sec) ||
            get_user(ts.tv_nsec, &timeout->tv_nsec))
            return -EFAULT;
        if (ts.tv_nsec > 999999999)
            return -EINVAL;
    }

    kmsg = compat_alloc_user_space(vlen * sizeof(struct mmsghdr));
    if (copy_in_user(kmsg, mmsg, vlen * sizeof(struct mmsghdr)))
        return -EFAULT;

    iov = compat_alloc_user_space(vlen * sizeof(struct iovec));
    if (copy_in_user(iov, mmsg->msg_hdr.msg_iov, vlen * sizeof(struct iovec)))
        return -EFAULT;

    addr = compat_alloc_user_space(vlen * sizeof(struct sockaddr));
    if (copy_in_user(addr, mmsg->msg_hdr.msg_name, vlen * sizeof(struct sockaddr)))
        return -EFAULT;

    ret = recvmmsg(fd, kmsg, vlen, flags, timeout ? &ts : NULL);
    if (ret > 0) {
        for (i = 0; i < ret; i++) {
            if (copy_to_user(&mmsg[i].msg_hdr, &kmsg[i].msg_hdr,
                             sizeof(struct mmsghdr)))
                return -EFAULT;
        }
    }

    return ret;
}

long compat_recvmmsg_time32(int fd, struct compat_mmsghdr __user *mmsg,
                            unsigned int vlen, unsigned int flags,
                            struct compat_timespec __user *timeout)
{
    long ret;
    struct timespec ts = { 0, 0 };
    struct mmsghdr *mmsg_native = NULL;
    struct compat_mmsghdr compat_mmsg;
    unsigned int i;
    int err;

    if (timeout) {
        if (get_user(ts.tv_sec, &timeout->tv_sec) ||
            get_user(ts.tv_nsec, &timeout->tv_nsec))
            return -EFAULT;
    }

    mmsg_native = kmalloc_array(vlen, sizeof(*mmsg_native), GFP_KERNEL);
    if (!mmsg_native)
        return -ENOMEM;

    for (i = 0; i < vlen; i++) {
        if (copy_from_user(&compat_mmsg, mmsg + i, sizeof(compat_mmsg)))
            return -EFAULT;

        mmsg_native[i].msg_hdr.msg_name    = compat_mmsg.msg_hdr.msg_name;
        mmsg_native[i].msg_hdr.msg_namelen = compat_mmsg.msg_hdr.msg_namelen;
        mmsg_native[i].msg_hdr.msg_iov    = compat_mmsg.msg_hdr.msg_iov;
        mmsg_native[i].msg_hdr.msg_iovlen = compat_mmsg.msg_hdr.msg_iovlen;
        mmsg_native[i].msg_hdr.msg_control = compat_mmsg.msg_hdr.msg_control;
        mmsg_native[i].msg_hdr.msg_controllen = compat_mmsg.msg_hdr.msg_controllen;
        mmsg_native[i].msg_hdr.msg_flags   = compat_mmsg.msg_hdr.msg_flags;
        mmsg_native[i].msg_len = compat_mmsg.msg_len;
    }

    ret = kernel_recvmmsg(fd, mmsg_native, vlen, flags, timeout ? &ts : NULL);
    if (ret >= 0) {
        for (i = 0; i < ret; i++) {
            compat_mmsg.msg_hdr.msg_name    = mmsg_native[i].msg_hdr.msg_name;
            compat_mmsg.msg_hdr.msg_namelen = mmsg_native[i].msg_hdr.msg_namelen;
            compat_mmsg.msg_hdr.msg_iov    = mmsg_native[i].msg_hdr.msg_iov;
            compat_mmsg.msg_hdr.msg_iovlen = mmsg_native[i].msg_hdr.msg_iovlen;
            compat_mmsg.msg_hdr.msg_control = mmsg_native[i].msg_hdr.msg_control;
            compat_mmsg.msg_hdr.msg_controllen = mmsg_native[i].msg_hdr.msg_controllen;
            compat_mmsg.msg_hdr.msg_flags   = mmsg_native[i].msg_hdr.msg_flags;
            compat_mmsg.msg_len = mmsg_native[i].msg_len;

            if (copy_to_user(mmsg + i, &compat_mmsg, sizeof(compat_mmsg))) {
                err = -EFAULT;
                ret = err;
                break;
            }
        }
    }

    kfree(mmsg_native);
    return ret;
}

long compat_recvmmsg_time32(int fd, struct compat_mmsghdr __user *mmsg,
                            unsigned int vlen, unsigned int flags,
                            struct compat_timespec __user *timeout)
{
    long ret;

    if (flags & ~(MSG_DONTWAIT|MSG_TRUNC|MSG_CMSG_CLOEXEC))
        return -EINVAL;

    if (timeout) {
        struct timespec ts;
        if (get_user(ts.tv_sec, &timeout->tv_sec) ||
            get_user(ts.tv_nsec, &timeout->tv_nsec))
            return -EFAULT;
        timeout = compat_ptr((unsigned long)&ts);
    }

    ret = kernel_recvmmsg(fd, mmsg, vlen, flags, timeout);
    return ret;
}
